adapter:
function adapt(input, solve, kit) {
  const [values, pos] = input;
  const nodes = kit.listNodes(values);
  const target = pos >= 0 ? nodes[pos] : null;
  if (nodes.length > 0) nodes[nodes.length - 1].next = target;
  // LeetCode passes only the head; pos just describes how the list was built.
  const result = solve(nodes[0] || null);
  const intact = nodes.every((node, i) => node.val === values[i] && node.next === (i + 1 < nodes.length ? nodes[i + 1] : target));
  if (!intact) throw new Error('The linked list must not be modified.');
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (result === null) return -1;
  const index = nodes.indexOf(result);
  if (index < 0) throw new Error('Return a node of the input list, or null.');
  return index;
}

validator:
function validate([head, pos]) {
  if (head.length > 10000) return 'The list has at most 10^4 nodes.';
  if (head.some(v => v < -100000 || v > 100000)) return 'Node values are between -10^5 and 10^5.';
  if (pos !== -1 && (pos < 0 || pos >= head.length)) return 'pos is -1 or the index of a node in the list.';
  return null;
}

