function generate(rand, size) {
  const n = size === 'large' ? 2000 : Math.floor(rand() * 9);
  const span = size === 'large' ? 100000 : 3;
  const head = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  const pos = n === 0 || rand() < 0.3 ? -1 : Math.floor(rand() * n);
  return [head, pos];
}
